package com.resumethinking.platform.matching;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="analysis_results")
public class AnalysisResultEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="task_id",nullable=false,unique=true,columnDefinition="BINARY(16)") private UUID taskId; @Column(name="resume_id",nullable=false,columnDefinition="BINARY(16)") private UUID resumeId; @Column(name="resume_version",nullable=false) private long resumeVersion; @Lob @Column(name="payload_json",nullable=false,columnDefinition="JSON") private String payloadJson; @Column(name="completed_at",nullable=false) private Instant completedAt; protected AnalysisResultEntity(){} public AnalysisResultEntity(AnalysisResult r,String json){taskId=r.taskId();resumeId=r.resumeId();resumeVersion=r.resumeVersion();payloadJson=json;completedAt=r.completedAt();} public UUID getTaskId(){return taskId;} public String getPayloadJson(){return payloadJson;} public Instant getCompletedAt(){return completedAt;} }
